* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: sans-serif;
}

html {
  font-size: 100%;
}

nav {
  background: #0b3d91;
}

nav ul {
  display: flex;
  flex-direction: column;
  list-style: none;
  margin: 0;
  padding: 1rem;
  gap: 0.75rem;
}

nav a {
  color: #fff;
  text-decoration: none;
  display: block;
  padding: 0.5rem 0;
}

@media (min-width: 700px) {
  nav ul {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.hero {
  width: 100%;
  max-width: 60rem;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
  padding: 1.5rem;
}

.hero h1 {
  font-size: 2rem;
  margin: 0 0 0.75rem;
}

.hero p {
  font-size: 1rem;
  color: #444;
}

.hero img {
  max-width: 100%;
  height: auto;
  display: block;
}

@media (min-width: 900px) {
  .hero {
    grid-template-columns: 1fr 1fr;
    align-items: center;
  }
}

.features {
  width: 100%;
  max-width: 60rem;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  padding: 0 1.5rem 1.5rem;
}

.feature-card {
  padding: 1rem;
  border: 1px solid #ddd;
  border-radius: 6px;
}

@media (min-width: 600px) {
  .features {
    grid-template-columns: repeat(3, 1fr);
  }
}
